"""Build the Wiki first, resolve teaching claims from it, then render HTML.
The LLM-authored content is reviewed in this conversation, not generated by a hidden API.
"""
from pathlib import Path
from datetime import datetime, timezone
from html import escape as e
import json
import re
import hashlib

ROOT=Path(__file__).resolve().parents[1]
TITLE='出發前，先查證'

def load(path):return json.loads((ROOT/path).read_text(encoding='utf-8'))
def save(path,value):
    p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(value,encoding='utf-8',newline='\n')
def dump(path,value):save(path,json.dumps(value,ensure_ascii=False,indent=2)+'\n')

def source_refs(ids,prefix=''):
    return ' '.join(f'<a class="source-tag" href="{prefix}sources.html#{s}">{s}</a>' for s in dict.fromkeys(ids))

def shell(title,description,body,prefix='',deck=False):
    return f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description)}"><meta name="theme-color" content="#18374b"><title>{e(title)}｜{TITLE}</title><link rel="icon" type="image/svg+xml" href="{prefix}assets/mark.svg"><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/app.js" defer></script></head><body{' class="deck-page"' if deck else ''}><a class="skip" href="#main">跳至主內容</a><header class="site-header shell"><a class="brand" href="{prefix}index.html"><span class="brand-icon" aria-hidden="true">查</span><span>{TITLE}<small>TRAVEL KNOWLEDGE LAB</small></span></a><nav aria-label="主要導覽"><a href="{prefix}index.html#wiki-library">Wiki</a><a href="{prefix}slides.html">教學簡報</a><a href="{prefix}sources.html">來源</a><a href="{prefix}workflow.html">流程紀錄</a></nav></header>{body}<footer class="site-footer shell"><p>{TITLE} · 旅行準備與資訊查核</p><p>清大 112034058 工工大四 鄭宇辰 · AI 協作整理</p></footer></body></html>'''

def fact_box(c,prefix=''):
    label='來源事實' if c['kind']=='source_fact' else '本專案的方法整理'
    return f'<section class="fact-box" id="{c["id"]}"><div class="fact-meta"><span class="pill">{label}</span><span>{c["id"]}</span></div><h3>{e(c["title"])}</h3><p>{e(c["text"])}</p><div>{source_refs(c["sources"],prefix)}</div></section>'

def run():
    rid=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
    events=[]
    def log(node,status,**details):events.append({'time_utc':datetime.now(timezone.utc).isoformat(),'node':node,'status':status,**details})
    ingest=load('data/ingest.json');sources={s['id']:s for s in ingest['records']}
    try:
        log('source_gate','started')
        assert ingest['ready'] and len(sources)>=5,'At least five actual ingested sources required'
        review=load('data/source-review.json');reviewed={s['id']:s for s in review['sources']}
        for sid,s in sources.items():
            assert s['excerpt_check']=='passed' and (ROOT/'raw'/f'{sid}.md').is_file(),sid
            assert reviewed[sid]['approved'] and reviewed[sid]['sha256']==s['sha256'],f'Source review missing/stale: {sid}'
            assert reviewed[sid]['limits_confirmed'],f'Scope not reviewed: {sid}'
        log('source_gate','passed',sources=len(sources),reviewer=review['actor'])
        claims={c['id']:c for c in load('data/claims.json')};topics=load('data/topics.json');by_slug={t['slug']:t for t in topics}
        log('claim_review','started')
        evidence={x['id']:sid for sid,s in sources.items() for x in s['evidence']}
        for cid,c in claims.items():
            assert c['wiki'] in by_slug and c['kind'] in ('source_fact','method') and c['text'].strip(),cid
            assert c['sources'] and all(s in sources for s in c['sources']),cid
            if c['kind']=='source_fact':assert c['evidence'] and all(eid in evidence and evidence[eid] in c['sources'] for eid in c['evidence']),cid
        assert len({x for c in claims.values() for x in c['sources']})>=5
        log('claim_review','passed',facts=sum(c['kind']=='source_fact' for c in claims.values()),methods=sum(c['kind']=='method' for c in claims.values()),semantic_review='docs/curation-review.json; program checks references, not truth')
        log('wiki_generation','started')
        for t in topics:
            assert all(x in claims and claims[x]['wiki']==t['slug'] for x in t['claim_ids'])
            assert all(x in by_slug and x!=t['slug'] for x in t['related'])
            lines=[f'# {t["title"]}',t['summary'],'## 閱讀範圍',t['context'],'## 知識點']
            for cid in t['claim_ids']:
                c=claims[cid];kind='來源事實' if c['kind']=='source_fact' else '本專案的方法整理'
                lines.extend([f'### {c["title"]}（{cid}）',f'<!-- claim:{cid} -->\n{c["text"]}\n<!-- /claim -->',f'類別：{kind}。依據：'+ '、'.join(f'[{s}](../sources.html#{s})' for s in c['sources'])])
            lines.extend(['## 可以怎麼準備',t['action'],'## 不能推論成',t['limit'],'## 延伸閱讀','\n'.join(f'- [{by_slug[s]["title"]}]({s}.md)' for s in t['related'])])
            save('wiki/'+t['slug']+'.md','\n\n'.join(lines)+'\n')
        save('wiki/index.md','# 旅行準備與資訊查核 Wiki\n\n'+'\n'.join(f'- [{t["title"]}]({t["slug"]}.md)' for t in topics)+'\n')
        log('wiki_generation','passed',knowledge_pages=len(topics),cross_links=sum(len(t['related']) for t in topics))
        log('wiki_query','started')
        plan=load('data/lesson-plan.json');resolved=[];query_log=[]
        for slide in plan['slides']:
            result=[]
            for cid in slide['claims']:
                assert cid in claims,f'Unknown claim {cid}'
                c=claims[cid];path=ROOT/'wiki'/f'{c["wiki"]}.md';md=path.read_text(encoding='utf-8')
                m=re.search(r'<!-- claim:'+re.escape(cid)+r' -->\n(.*?)\n<!-- /claim -->',md,re.S)
                assert m and m[1]==c['text'],f'Wiki/claim drift: {cid}'
                result.append({'claim_id':cid,'text_from_wiki':m[1],'wiki':c['wiki'],'kind':c['kind'],'sources':c['sources']})
            resolved.append({**slide,'knowledge':result})
            query_log.append({'slide':slide['id'],'query':slide['title'].replace('\n',''),'requested_claims':slide['claims'],'wiki_files':list(dict.fromkeys(x['wiki']+'.md' for x in result)),'retrieved_claims':len(result)})
        lesson={**plan,'status':'已從Wiki實際解析知識點','slides':resolved}
        dump('data/lesson.json',lesson);dump('data/wiki-query-log.json',query_log)
        log('wiki_query','passed',slide_queries=len(query_log),retrieved_claims=sum(q['retrieved_claims'] for q in query_log))
        log('lesson_audit','started')
        assert len(resolved)>=10 and len(plan['objectives'])>=3
        assert len({s['id'] for s in resolved})==len(resolved)
        for slide in resolved:
            assert slide['knowledge'] and slide['title'] and slide['lead']
            assert all(x['wiki'] in by_slug for x in slide['knowledge'])
            if 'quiz' in slide:
                q=slide['quiz'];assert len(q['options'])>=2 and 0<=q['correct']<len(q['options']) and q['feedback']
        covered={sid for s in resolved for c in s['knowledge'] for sid in c['sources']}
        assert covered==set(sources),'Sources not represented in teaching'
        log('lesson_audit','passed',slides=len(resolved),mapped_source_documents=len(covered),quiz_questions=sum('quiz' in s for s in resolved))
        report={'run_id':rid,'time_utc':datetime.now(timezone.utc).isoformat(),'ingested_sources':len(sources),'wiki_pages':len(topics),'claims':len(claims),'slides':len(resolved),'status':'passed','events':events}
        log('html_generation','started')
        render(sources,topics,claims,lesson,report)
        log('html_generation','passed',generated_pages=10)
        report['events']=events;dump('data/build-report.json',report);dump('docs/build-'+rid+'.json',report)
        # Re-render workflow after the final event has been committed to the report.
        render_workflow(report)
        print(json.dumps({k:v for k,v in report.items() if k!='events'},ensure_ascii=False))
    except Exception as exc:
        node=next((x['node'] for x in reversed(events) if x['status']=='started'),'source_gate')
        routes={'source_gate':'取得來源／來源範圍審核','claim_review':'AI整理知識點','wiki_generation':'Wiki結構整理','wiki_query':'Wiki知識與分頁稿','lesson_audit':'教學分頁稿','html_generation':'HTML產生器'}
        log(node,'failed',error=str(exc),return_to=routes[node])
        dump('docs/build-'+rid+'-failed.json',{'run_id':rid,'status':'failed','events':events})
        raise

def render(sources,topics,claims,lesson,report):
    topic_map={t['slug']:t for t in topics}
    cards=''.join(f'<a class="wiki-card" href="wiki/{t["slug"]}.html" data-search="{e(t["title"]+t["summary"]+" ".join(claims[c]["text"] for c in t["claim_ids"]))}"><span class="eyebrow">WIKI NOTE</span><h3>{e(t["title"])}</h3><p>{e(t["summary"])}</p><span class="card-meta">'+('方法整理' if t['slug']=='verification-method' else '有來源的知識頁')+'</span></a>' for t in topics)
    body=f'''<main id="main"><section class="hero shell"><div><p class="eyebrow">給初次自由行的大學生</p><h1>把資訊查清楚，<br><span>再把行李收好。</span></h1><p class="hero-lead">從官方資料到自己的行前清單。<br>學會找來源、讀條件，也知道什麼時候該再確認。</p><div class="hero-actions"><a class="button primary" href="slides.html">開始教學簡報</a><a class="button" href="#wiki-library">閱讀 Wiki</a></div><p class="micro">建議教學時間約15分鐘 · 使用方向鍵翻頁 · 手機也能閱讀</p></div><div class="hero-board"><p class="eyebrow">一個問題，留一份依據</p><h2>這則資訊，<br>適用我的行程嗎？</h2><div class="audit-grid"><div><span>誰發布</span><strong>來源單位</strong></div><div><span>何時發布</span><strong>資料日期</strong></div><div><span>給誰使用</span><strong>適用對象</strong></div><div><span>有何前提</span><strong>限制條件</strong></div></div><p>本專案提出的查核方法，非通用旅行規定。</p></div></section><section class="stats shell" aria-label="作品內容"><div><strong>{len(sources)}</strong><span>已收錄的真實文件</span></div><div><strong>{len(topics)}</strong><span>互相連結的知識頁</span></div><div><strong>{len(lesson['slides'])}</strong><span>教學分頁</span></div><a href="workflow.html">查看實際執行與修正紀錄</a></section><section class="library shell" id="wiki-library"><div class="section-head"><div><p class="eyebrow">KNOWLEDGE BEFORE SLIDES</p><h2>先建立 Wiki，讓知識有來處。</h2></div><label class="search-label">搜尋知識頁<input type="search" id="wiki-search" placeholder="例如：行李、條件、天氣"></label></div><p id="wiki-count" role="status">共{len(topics)}篇知識頁</p><div class="wiki-grid">{cards}</div><p id="wiki-empty" hidden>沒有符合的知識頁，請換個關鍵字。</p></section><section class="path-section shell"><div><p class="eyebrow">FOLLOW THE EVIDENCE</p><h2>不只看最後一份簡報。</h2><p>每個教學知識點都能回到 Wiki，再找到原始來源。也能查看取得、整理、檢查到生成的執行紀錄。</p></div><div class="path-links"><a href="sources.html"><strong>來源與摘錄</strong><span>文件、版本、取得時間與適用範圍</span></a><a href="workflow.html"><strong>工作流程與反思</strong><span>重複步驟、退回路徑與實際修訂</span></a><a href="AGENTS.md"><strong>AI 維護規則</strong><span>新增資料與重新生成時要遵守的方式</span></a></div></section></main>'''
    save('index.html',shell('旅行準備與資訊查核','由五份官方文件建立Wiki，再產生給自由行新手的教學HTML簡報。',body))
    for t in topics:
        knowledge=''.join(fact_box(claims[c],'../') for c in t['claim_ids'])
        related=''.join(f'<a href="{slug}.html">{e(topic_map[slug]["title"])}</a>' for slug in t['related'])
        body=f'''<main class="shell article-page" id="main"><nav class="breadcrumb" aria-label="麵包屑"><a href="../index.html#wiki-library">Wiki目錄</a><span>／</span><span>知識頁</span></nav><header class="article-heading"><p class="eyebrow">TRAVEL WIKI</p><h1>{e(t['title'])}</h1><p>{e(t['summary'])}</p></header><div class="article-grid"><article><section><h2>閱讀範圍</h2><p>{e(t['context'])}</p></section>{knowledge}<section class="action-box"><span class="eyebrow">本專案的行動建議</span><h2>可以怎麼準備</h2><p>{e(t['action'])}</p></section><section><h2>不能推論成</h2><p>{e(t['limit'])}</p></section><section><h2>延伸閱讀</h2><div class="related-links">{related}</div></section></article><aside class="side-note"><p class="eyebrow">從哪裡來，到哪裡用</p><h3>有依據，也保留限制。</h3><p>F開頭是來源事實；M開頭是本專案提出的方法。兩者分開，方便核對。</p><a href="../slides.html">開啟教學簡報</a><a href="{t['slug']}.md">閱讀 Markdown 原稿</a></aside></div></main>'''
        save(f'wiki/{t["slug"]}.html',shell(t['title'],t['summary'],body,'../'))
    source_cards=[]
    for sid,s in sources.items():
        original=s.get('discovery_title');note=f'<p class="review-note">題名已核對：工具顯示「{e(original)}」，封面實為「{e(s["title"])}」。</p>' if original else ''
        source_cards.append(f'''<article class="source-card" id="{sid}"><div class="source-heading"><span class="pill">{sid} · 已收錄</span><span>{e(s['kind'].upper())}</span></div><h2>{e(s['title'])}</h2><p>{e(s['publisher'])}</p><dl><div><dt>原始日期</dt><dd>{e(s['published'])}</dd></div><div><dt>本次取得</dt><dd>{e(s['retrieved_utc'][:10])}（UTC日期）</dd></div><div><dt>適用範圍</dt><dd>{e(s['scope'])}</dd></div><div><dt>文件定位</dt><dd>{e(s.get('page_label','HTML正文；以收錄摘錄定位'))}</dd></div></dl>{note}<div class="source-links"><a href="{e(s['url'])}" target="_blank" rel="noopener noreferrer">開啟官方原文</a><a href="raw/{sid}.md">查看短摘錄與取得紀錄</a></div><details><summary>查看下載識別資料</summary><p class="hash">SHA-256：{s['sha256']}</p><p>HTTP {s['http_status']} · {s['bytes']:,} bytes。成功取得只代表文件可讀，不代表內容永遠適用。</p></details></article>''')
    body='<main id="main" class="shell sources-page"><header class="article-heading"><p class="eyebrow">SOURCE REGISTER</p><h1>五份真實資料，各有適用範圍。</h1><p>下面是本次收錄的文件與查核快照。只公開必要短摘錄，完整文件請回原始網站閱讀。</p></header><div class="source-grid">'+''.join(source_cards)+'</div></main>'
    save('sources.html',shell('來源與收錄紀錄','五份實際取得的官方文件，含日期、適用範圍及短摘錄。',body))
    slides=[];options=[]
    for i,s in enumerate(lesson['slides']):
        cid=s['id'];options.append(f'<option value="{i}">{i+1}／{len(lesson["slides"])}　{e(s["title"].replace(chr(10),""))}</option>')
        cards=''.join(f'<div class="lesson-card"><h3>{e(c["title"])}</h3><p>{e(c["body"])}</p></div>' for c in s['cards'])
        if s['layout']=='sources':
            cards=''.join(f'<a class="source-mini" href="sources.html#{sid}"><strong>{sid}</strong><span>{e(src["title"])}<small>{e(src["published"])}</small></span></a>' for sid,src in sources.items())
        quiz=''
        if 'quiz' in s:
            q=s['quiz'];choices=''.join(f'<label class="quiz-option"><input type="radio" name="quiz-{cid}" value="{j}"><span>{e(opt)}</span></label>' for j,opt in enumerate(q['options']))
            quiz=f'<fieldset class="quiz" data-answer="{q["correct"]}" data-feedback="{e(q["feedback"])}"><legend>{e(q["question"])}</legend>{choices}<button class="button check-answer" type="button" hidden>確認答案</button><p class="quiz-feedback" role="status"></p></fieldset>'
        refs=''.join(f'<li><a href="wiki/{x["wiki"]}.html#{x["claim_id"]}">{x["claim_id"]} · {e(claims[x["claim_id"]]["title"])}</a><span>{"方法整理" if x["kind"]=="method" else "來源事實"}</span><p>{e(x["text_from_wiki"])}</p>{source_refs(x["sources"])}</li>' for x in s['knowledge'])
        slides.append(f'<section class="slide layout-{s["layout"]}" id="slide-{cid}" aria-labelledby="title-{cid}" data-slide-index="{i}"><div class="slide-top"><p class="eyebrow">{e(s["kicker"])}</p><span class="page-marker">{i+1}／{len(lesson["slides"])}</span></div><h2 id="title-{cid}">{e(s["title"]).replace(chr(10),"<br>")}</h2><p class="slide-lead">{e(s["lead"])}</p><div class="lesson-cards cards-{len(s["cards"])}">{cards}</div>{quiz}<details class="slide-evidence"><summary>Wiki依據與來源（{len(s["knowledge"])}個知識點）</summary><ul>{refs}</ul></details></section>')
    body=f'<main id="main" class="shell deck-main"><h1 class="sr-only">旅行準備與資訊查核：教學HTML簡報</h1><div class="deck-context"><span>建議教學約15分鐘 · 初次自由行的大學生</span><a href="index.html#wiki-library">返回Wiki目錄</a></div><noscript><p class="notice">未啟用JavaScript：以下顯示全部教學頁，可以捲動閱讀；測驗可參考Wiki自行核對。</p></noscript><div class="slides">'+''.join(slides)+f'</div><nav class="deck-controls" aria-label="簡報控制" hidden><button type="button" id="slide-prev">上一頁</button><label><span class="sr-only">選擇教學頁</span><select id="slide-select">'+''.join(options)+'</select></label><button type="button" id="slide-next">下一頁</button></nav><p id="slide-status" class="sr-only" aria-live="polite"></p></main>'
    save('slides.html',shell('教學HTML簡報','以Wiki為知識來源的14頁旅行資訊查核教學，包含練習與逐頁對應。',body,deck=True))
    render_workflow(report)

def render_workflow(report):
    ingest=load('data/ingest.json');curation=load('docs/curation-review.json')
    interface=load('docs/interface-review.json')
    important=[x for x in ingest['events'] if x['status'] in ('failed','issue_found','resolved')]
    source_events=''.join(f'<li><strong>{e(x["node"])} · {e(x["status"])}</strong><p>{e(x.get("problem",x.get("resolution",x.get("error",""))))}</p><small>{e(x["source"] or "")} · {e(x["time_utc"])}</small></li>' for x in important)
    build_events=''.join(f'<tr><th scope="row">{e(x["node"])}</th><td>{e(x["status"])}</td><td>{e(x["time_utc"][11:19])} UTC</td></tr>' for x in report['events'])
    reviews=''.join(f'<article class="review-card"><h3>{e(x["claim"])}</h3><p><strong>初稿：</strong>{e(x["before"])}</p><p><strong>修訂：</strong>{e(x["after"])}</p><p>{e(x["reason"])}</p></article>' for x in curation['changes'])
    qa_path=ROOT/'data/browser-qa.json'
    if qa_path.exists():
        qa=load('data/browser-qa.json');qa_text=f'實際瀏覽器驗證：{qa["passed"]}項通過。'+e('；'.join(qa['checks']))
    else:qa_text='目前尚未寫入瀏覽器檢查結果；來源與建置檢查不能代替瀏覽器驗證。'
    body=f'''<main id="main" class="shell workflow-page"><header class="article-heading"><p class="eyebrow">THE WORK BEHIND THE KNOWLEDGE</p><h1>從資料到簡報，<br>每一步都能回頭查。</h1><p>LLM在本次協作中閱讀、整理與修訂；Python負責取得、驗證、查詢Wiki與建置。沒有額外呼叫未揭露的模型API。</p></header><section><h2>Loop／Graph怎麼設計</h2><ol class="flow-nodes"><li><strong>取得文件</strong><span>實際下載、日期與雜湊</span></li><li><strong>來源範圍審核</strong><span>題名、版本、業者與用途</span></li><li><strong>整理成Wiki</strong><span>來源事實與方法分開</span></li><li><strong>查詢Wiki</strong><span>解析知識點與相關頁</span></li><li><strong>寫分頁稿並檢查</strong><span>每頁都對應Wiki</span></li><li><strong>生成HTML與驗證</strong><span>頁面、連結與互動</span></li></ol><div class="return-map"><h3>失敗後回到哪裡？</h3><ul><li>文件或摘錄不可用：回到來源選擇／擷取。</li><li>版本、題名或適用範圍不清：回到來源審核，先不寫入Wiki。</li><li>Wiki缺依據：回到知識整理。</li><li>分頁稿找不到Wiki知識點：回到分頁稿與Wiki查詢。</li><li>頁面或互動失敗：回到HTML修正，再驗證。</li></ul><p>這個loop包含AI與程式交替工作。程式記錄退回節點並停止，修改後再執行；不宣稱是全自動的LLM自我修正。</p></div></section><section><h2>這次真正遇到的問題</h2><ul class="event-list">{source_events}</ul><p>來源題名不能只相信工具提供的標籤。這次檢查PDF封面後才確認正式題名，並保留2020年版本與第65頁的定位。</p><div class="review-grid">{reviews}</div></section><section><h2>把檢查往前移</h2><p>根據來源題名問題與整理草稿中混入建議的情況，在來源擷取之外，再加入獨立的「來源範圍審核」關卡，並於產生簡報前檢查Wiki知識對應。source-review.json綁定文件雜湊，來源變動時不能直接沿用舊審核。</p><p>這次最明顯的問題出現在來源整理與敘述邊界；只有五篇資料，不能據此推論長期最常失敗的節點。下載與建置檢查通過，也不代表內容永遠正確。</p></section><section><h2>一次實際執行</h2><p>來源執行ID：<code>{e(ingest['run_id'])}</code>；本次建置ID：<code>{e(report['run_id'])}</code>。</p><div class="table-wrap"><table><thead><tr><th>節點</th><th>狀態</th><th>時間</th></tr></thead><tbody>{build_events}</tbody></table></div><p class="qa-result">{qa_text}</p><div class="resource-links"><a href="data/ingest.json">來源取得紀錄</a><a href="data/build-report.json">建置紀錄</a><a href="data/wiki-query-log.json">Wiki查詢與分頁對應</a><a href="docs/curation-review.json">實際內容修訂</a></div></section><section class="action-box"><h2>AI協作與我的理解</h2><p>我提供作業要求並選定旅行主題與教學對象。AI協助資料閱讀、知識整理、簡報、程式、檢查與說明；這裡的理解文字也有AI協助整理。</p><p>我理解這次的重點，是讓知識的來源和生成順序能被核對。Wiki不是暫時把搜尋結果貼在一起，而是先整理成可連結、可更新的知識，再用它產生教學。把題名、條件和知識對應提早檢查，可以避免錯誤一路被複製到簡報。</p><a href="docs/discussion.md">查看主題討論整理</a></section></main>'''
    interface_note='<section><h2>手機版的實際修正</h2><p>'+e(interface['observation'])+'</p><p>'+e(interface['change'])+'</p><div class="resource-links"><a href="evidence/browser-qa-before-mobile-revision.json">修改前檢查</a><a href="data/browser-qa.json">修改後瀏覽器檢查</a><a href="evidence/03_天氣測驗_手機.png">修改後手機截圖</a></div></section>'
    body=body.replace('<section><h2>把檢查往前移</h2>',interface_note+'<section><h2>把檢查往前移</h2>')
    body=body.replace('</main>','<section><h2>成果與說明</h2><div class="resource-links"><a href="docs/report.md">完整作業說明</a><a href="evidence/01_Wiki首頁_桌機.png">Wiki首頁截圖</a><a href="evidence/02_四格查核教學_桌機.png">教學簡報截圖</a></div></section></main>')
    save('workflow.html',shell('工作流程與真實執行','來源取得、Wiki整理、教學生成的Loop與實際修正紀錄。',body))

